import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
import java.util.Stack;

/** Builds LeetCode-style inputs. Generated by the visualizer; never stepped through. */
final class __LC {
    private __LC() {}

    static <T> T linked(Class<T> cls, Object[] values, int cyclePos) throws Exception {
        if (values.length == 0) return null;
        Field next = selfField(cls, "next", null);
        Field prev = selfField(cls, "prev", next);
        Field val = valueField(cls);
        List<T> nodes = new ArrayList<>();
        for (Object v : values) nodes.add(make(cls, val, v));
        for (int i = 0; i + 1 < nodes.size(); i++) {
            next.set(nodes.get(i), nodes.get(i + 1));
            if (prev != null) prev.set(nodes.get(i + 1), nodes.get(i));
        }
        T last = nodes.get(nodes.size() - 1);
        if (cyclePos >= 0 && cyclePos < nodes.size()) {
            next.set(last, nodes.get(cyclePos));
            if (prev != null && cyclePos == 0) prev.set(nodes.get(0), last);
        }
        return nodes.get(0);
    }

    static <T> T tree(Class<T> cls, Object[] values) throws Exception {
        if (values.length == 0 || values[0] == null) return null;
        Field left = selfField(cls, "left", null);
        Field right = selfField(cls, "right", left);
        Field val = valueField(cls);
        T root = make(cls, val, values[0]);
        Queue<T> queue = new ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < values.length) {
            T node = queue.poll();
            if (i < values.length && values[i] != null) {
                T child = make(cls, val, values[i]);
                left.set(node, child);
                queue.add(child);
            }
            i++;
            if (right != null && i < values.length && values[i] != null) {
                T child = make(cls, val, values[i]);
                right.set(node, child);
                queue.add(child);
            }
            i++;
        }
        return root;
    }

    @SafeVarargs
    static <T> List<T> listOf(T... items) { return new ArrayList<>(Arrays.asList(items)); }

    @SafeVarargs
    static <T> Set<T> setOf(T... items) { return new HashSet<>(Arrays.asList(items)); }

    static <T> Stack<T> stackOf(List<T> items) {
        Stack<T> stack = new Stack<>();
        stack.addAll(items);
        return stack;
    }

    @SuppressWarnings("unchecked")
    static <K, V> Map<K, V> mapOf(Object... keysAndValues) {
        Map<K, V> map = new HashMap<>();
        for (int i = 0; i + 1 < keysAndValues.length; i += 2) map.put((K) keysAndValues[i], (V) keysAndValues[i + 1]);
        return map;
    }

    private static <T> T make(Class<T> cls, Field val, Object value) throws Exception {
        for (Constructor<?> c : cls.getDeclaredConstructors()) {
            if (c.getParameterCount() == 1 && wraps(c.getParameterTypes()[0], val.getType())) {
                c.setAccessible(true);
                return cls.cast(c.newInstance(value));
            }
        }
        Constructor<T> c = cls.getDeclaredConstructor();
        c.setAccessible(true);
        T node = c.newInstance();
        val.set(node, value);
        return node;
    }

    private static boolean wraps(Class<?> a, Class<?> b) { return a.equals(b); }

    private static Field selfField(Class<?> cls, String preferred, Field exclude) {
        Field fallback = null;
        for (Field f : cls.getDeclaredFields()) {
            if (Modifier.isStatic(f.getModifiers()) || !f.getType().equals(cls) || f.equals(exclude)) continue;
            f.setAccessible(true);
            if (f.getName().equals(preferred)) return f;
            if (fallback == null) fallback = f;
        }
        return fallback;
    }

    private static Field valueField(Class<?> cls) {
        Field fallback = null;
        for (Field f : cls.getDeclaredFields()) {
            if (Modifier.isStatic(f.getModifiers()) || f.getType().equals(cls)) continue;
            f.setAccessible(true);
            String n = f.getName();
            if (n.equals("val") || n.equals("value") || n.equals("data") || n.equals("key")) return f;
            if (fallback == null) fallback = f;
        }
        if (fallback == null) throw new IllegalArgumentException(cls.getSimpleName() + " has no value field");
        return fallback;
    }
}
